@startuml

class Building {
  + m : int
}

class Floor {
  + floorNumber : int
}

class Elevator {
  + id : int
}

class FloorButton {
  + direction : string
  + isLit : boolean
}

class ElevatorButton {
  + isLit : boolean
}

Building "1" *-- "m" Floor
Building "1" -- "*" Elevator
Elevator "1" -- "*" ElevatorButton
Floor "1" -- "*" FloorButton
Elevator "1" -- "*" FloorButton : services

@enduml

